int fdset_new_array(FDSet **ret, const int *fds, unsigned n_fds) { /* <=== fdset_new_array */ 
        unsigned i;
        FDSet *s;
        int r;

        assert(ret);

        s = fdset_new();
        if (!s)
                return -ENOMEM;

        for (i = 0; i < n_fds; i++) {

                r = fdset_put(s, fds[i]);
                if (r < 0) {
                        set_free(MAKE_SET(s));
                        return r;
                }
        }

        *ret = s;
        return 0;
}

int set_put(Set *s, const void *key) { /* <=== set_put */ 
        struct swap_entries swap;
        struct hashmap_base_entry *e;
        unsigned hash, idx;

        assert(s);

        hash = bucket_hash(s, key);
        idx = bucket_scan(s, hash, key);
        if (idx != IDX_NIL)
                return 0;

        e = &bucket_at_swap(&swap, IDX_PUT)->p.b;
        e->key = key;
        return hashmap_put_boldly(s, hash, &swap, true);
}

static inline Set *set_free(Set *s) { /* <=== set_free */ 
        internal_hashmap_free(HASHMAP_BASE(s));
        return NULL;
}

HashmapBase *internal_hashmap_free(HashmapBase *h) { /* <=== internal_hashmap_free */ 

        /* Free the hashmap, but nothing in it */

        if (h) {
                internal_hashmap_clear(h);
                hashmap_free_no_clear(h);
        }

        return NULL;
}

